CREATE TEMP TABLE logins ON COMMIT DROP AS
SELECT sal.student_id, sal.user_id
  FROM student_account_links sal
  JOIN users u ON u.user_id = sal.user_id
  JOIN ctx ON sal.school_year_id = ctx.year_id
 WHERE u.password <> '!';

